      { id: 2, question: 'What does the 304 status code indicate?', options: ['Resource moved permanently', 'Not modified — use cached version', 'Internal server error', 'Unauthorized access'], correctIndex: 1, explanation: '304 Not Modified means the resource has not changed since the last request, so the browser can use its cached copy.' },
      { id: 3, question: 'What is the primary advantage of HTTP/2 over HTTP/1.1?', options: ['Larger headers', 'Multiplexing multiple requests over a single connection', 'Plain text instead of binary', 'No need for TLS'], correctIndex: 1, explanation: 'HTTP/2 introduced multiplexing, allowing multiple requests and responses simultaneously over a single TCP connection.' }
