      { id: 1, question: 'Which versioning strategy embeds the version directly in the URL?', options: ['Header versioning', 'Query parameter versioning', 'URL path versioning', 'Content negotiation'], correctIndex: 2, explanation: 'URL path versioning places the version in the path, e.g., /api/v1/users, making it explicit and easy to identify.' },
      { id: 2, question: 'What header is commonly used for API versioning via content negotiation?', options: ['X-API-Version', 'Accept', 'Content-Type', 'Authorization'], correctIndex: 1, explanation: 'The Accept header can include version information, e.g., Accept: application/vnd.myapp.v2+json, enabling content-based versioning.' },
      { id: 3, question: 'What is a major risk of URL versioning?', options: ['URLs become too short', 'Cached responses may serve stale versions', 'Cannot be used with load balancers', 'Only supports GET requests'], correctIndex: 1, explanation: 'URL versioning can cause caching issues because different versions share CDN and browser caches, potentially serving outdated responses.' }
